package com.example.configservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1")
public class ConfigServiceApplication {

    private static final Map<String, Object> BASE_CONFIG = new ConcurrentHashMap<>();
    private static final ObjectMapper mapper = new ObjectMapper();

    @Autowired
    private JdbcTemplate jdbcTemplate;

    static {
        BASE_CONFIG.put("theme", "default");
        BASE_CONFIG.put("locale", "en_US");
        BASE_CONFIG.put("maxRetries", 3);
        BASE_CONFIG.put("timeout", 5000);
        BASE_CONFIG.put("isAdmin", false);
    }

    public static void main(String[] args) {
        SpringApplication.run(ConfigServiceApplication.class, args);
    }

    // Deep merge user preferences into base config
    @PostMapping("/config/merge")
    public Map<String, Object> mergeConfig(@RequestBody String body) throws Exception {
        JsonNode input = mapper.readTree(body);
        Map<String, Object> userConfig = mapper.convertValue(input, Map.class);
        Map<String, Object> result = new ConcurrentHashMap<>(BASE_CONFIG);
        deepMerge(result, userConfig);
        return result;
    }

    // Fetch config and persist user preference
    @PostMapping("/config/save")
    public Map<String, Object> saveConfig(@RequestBody String body) throws Exception {
        JsonNode input = mapper.readTree(body);
        Map<String, Object> userConfig = mapper.convertValue(input, Map.class);

        // Merge into shared config (vulnerability: pollutes shared state)
        deepMerge(BASE_CONFIG, userConfig);

        // Attempt to persist to database
        String userId = (String) userConfig.getOrDefault("userId", "anonymous");
        String configJson = mapper.writeValueAsString(BASE_CONFIG);

        try {
            jdbcTemplate.update(
                "INSERT INTO user_configs (user_id, config_data, updated_at) VALUES (?, ?::jsonb, NOW()) " +
                "ON CONFLICT (user_id) DO UPDATE SET config_data = ?::jsonb, updated_at = NOW()",
                userId, configJson, configJson
            );
        } catch (Exception e) {
            // Log but don't fail - config is still in memory
            System.err.println("DB persist failed: " + e.getMessage());
        }

        return BASE_CONFIG;
    }

    @GetMapping("/config")
    public Map<String, Object> getConfig() {
        return BASE_CONFIG;
    }

    @GetMapping("/admin/users")
    public List<Map<String, Object>> listUsers() {
        Boolean isAdmin = (Boolean) BASE_CONFIG.getOrDefault("isAdmin", false);
        if (!isAdmin) {
            throw new RuntimeException("Forbidden: admin access required");
        }
        return jdbcTemplate.queryForList("SELECT user_id, config_data FROM user_configs");
    }

    @SuppressWarnings("unchecked")
    private void deepMerge(Map<String, Object> target, Map<String, Object> source) {
        for (Map.Entry<String, Object> entry : source.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();
            if (value instanceof Map && target.get(key) instanceof Map) {
                deepMerge((Map<String, Object>) target.get(key), (Map<String, Object>) value);
            } else {
                target.put(key, value);
            }
        }
    }
}
